/** A validated re-settle: who takes it, and (once applied) the figure the claim was settled at before. */
public class ClaimResettle {
    private final String user;
    private BigDecimal old;

    public ClaimResettle(String user) {
        this.user = user;
    }

    public String user() { return user; }
    public BigDecimal old() { return old; }
    public void setOld(BigDecimal old) { this.old = old; }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.ClosedPeriods;
import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.settings.Role;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Val;

/** Re-settles a SETTLED claim: only a steward may, and never one dated in a closed period. Its due is
 *  fixed again at the figure it would have today as an OPEN claim bound by no statement: the rate of
 *  its person's grade in force on its date, at least the sheet's floor, plus its late charge today
 *  (n/a with no rate). It stays SETTLED, keeps its number and its binding. */
public class ApplyClaimResettle {
    public void apply(@Val ClaimResettle change, @Val Claim claim, People people, Figures figures,
            ClosedPeriods closedPeriods, Settings settings) throws ClaimStatusRefusedException, PeriodClosedException {
        if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD) {
            throw new ClaimStatusRefusedException("Only a steward can re-settle a claim");
        }
        if (claim.getStatus() != ClaimStatus.SETTLED) {
            throw new ClaimStatusRefusedException("Only a SETTLED claim can be re-settled");
        }
        closedPeriods.refuse(claim.getSheetId(), claim.getDate());
        Claim open = new Claim(claim.getId(), claim.getSheetId(), claim.getPersonId(), claim.getAmount(),
                claim.getDate(), claim.getNote(), ClaimStatus.OPEN, claim.getNumber(), null, claim.getOpenedBy());
        open.setCorrects(claim.getCorrects());
        open.setDueBy(claim.getDueBy());
        String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
        change.setOld(claim.getDue());
        claim.setDue(figures.due(open, grade));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Runs after the claim is saved, so a refused re-settle writes no log or audit line. */
public class RecordClaimResettled {
    public void record(@Val ClaimResettle change, @Val Claim claim, People people, ClaimLog log, Audit audit) {
        log.write(claim, change.user());
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.record("CLAIM_RESETTLED sheet=" + claim.getSheetId() + " by=" + change.user()
                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
                + " date=" + claim.getDate() + (claim.getNumber() != null ? " number=" + claim.getNumber() : "")
                + " old=" + figure(change.old()) + " new=" + figure(claim.getDue()));
    }

    private static String figure(BigDecimal due) {
        return due != null ? due.toPlainString() : "n/a";
    }
}
package net.officefloor.hq.app.claim;

/** A status change the claim's current status does not allow; answered 409. */
public class ClaimStatusRefusedException extends Exception {
    public ClaimStatusRefusedException(ClaimStatus from, ClaimAction action) {
        super("A " + from + " claim cannot be " + action.to());
    }

    public ClaimStatusRefusedException(String message) {
        super(message);
    }
}
