83	import org.springframework.jdbc.core.JdbcTemplate;
84	import org.springframework.jdbc.support.GeneratedKeyHolder;
85	import org.springframework.stereotype.Repository;
86	
87	/** The claims of each sheet, newest first: by when each was added, or last reassigned to another person. */
88	@Repository
89	public class Claims {
90	
91	    private static final String COLUMNS = "SELECT id, sheet_id, person_id, amount, claim_date, note, status, number, due, opened_by, stated, stated_due, corrects, due_by FROM claim";
92	
93	    private final JdbcTemplate jdbc;
94	
95	    public Claims(JdbcTemplate jdbc) {
96	        this.jdbc = jdbc;
97	    }
98	
99	    public List<Claim> onSheet(String sheetId) {
100	        return jdbc.query(COLUMNS + " WHERE sheet_id = ? ORDER BY listed DESC", Claims::claim, sheetId);
101	    }
102	
103	    /** The claim with this id on this sheet, or null when there is none. Locks the claim's row for
104	     *  the rest of the transaction, so two changes to one claim at once happen one after the other. */
105	    public Claim find(String sheetId, long id) {
106	        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND id = ? FOR UPDATE", Claims::claim, sheetId, id)
107	                .stream().findFirst().orElse(null);
108	    }
109	
110	    /** The person's claims, newest first, each locked for the rest of the transaction. */
111	    public List<Claim> ofPerson(String sheetId, long personId) {
112	        return jdbc.query(COLUMNS + " WHERE sheet_id = ? AND person_id = ? ORDER BY listed DESC FOR UPDATE",
113	                Claims::claim, sheetId, personId);
114	    }
115	
116	    /** Whether the person has a SETTLED claim with this number: one a correction may correct. */
117	    public boolean settled(String sheetId, long personId, String number) {
118	        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ? AND status = 'SETTLED'",
119	                Integer.class, sheetId, personId, number);
120	        return n != null && n > 0;
121	    }
122	
123	    /** The date of the person's claim with this number, or null when there is none. */
124	    public LocalDate dateOf(String sheetId, long personId, String number) {
125	        return jdbc.query("SELECT claim_date FROM claim WHERE sheet_id = ? AND person_id = ? AND number = ?",
126	                (rs, i) -> rs.getDate("claim_date").toLocalDate(), sheetId, personId, number)
127	                .stream().findFirst().orElse(null);
128	    }
129	
130	    /** Move the claim to its (new) person: unbound from any statement, and listed as that person's newest claim. */
131	    public void reassign(Claim claim) {
132	        jdbc.update("UPDATE claim SET person_id = ?, stated = FALSE, stated_due = NULL, listed = NEXT VALUE FOR claim_listed WHERE id = ?",
133	                claim.getPersonId(), claim.getId());
134	    }
135	
136	    /** Insert a new claim (assigning its id) or update an existing one. */
137	    public void save(Claim claim) {
138	        if (claim.getId() != null) {
139	            jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ?, status = ?, number = ?, due = ?, opened_by = ?, stated = ?, stated_due = ?, corrects = ? WHERE id = ?",
140	                    claim.getAmount(), Date.valueOf(claim.getDate()), claim.getNote(), claim.getStatus().name(),
141	                    claim.getNumber(), claim.getDue(), claim.getOpenedBy(), claim.isStated(), claim.getStatedDue(), claim.getCorrects(), claim.getId());
142	            return;
143	        }
144	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
145	        jdbc.update(con -> {
146	            PreparedStatement ps = con.prepareStatement(
147	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status, corrects, due_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
148	                    new String[] { "id" });
149	            ps.setString(1, claim.getSheetId());
150	            ps.setLong(2, claim.getPersonId());
151	            ps.setBigDecimal(3, claim.getAmount());
152	            ps.setDate(4, Date.valueOf(claim.getDate()));
153	            ps.setString(5, claim.getNote());
154	            ps.setString(6, claim.getStatus().name());
155	            ps.setString(7, claim.getCorrects());
156	            ps.setDate(8, Date.valueOf(claim.getDueBy()));
157	            return ps;
158	        }, keys);
159	        claim.setId(keys.getKey().longValue());
160	    }
161	
162	    private static Claim claim(ResultSet rs, int i) throws SQLException {
163	        Claim claim = new Claim(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
164	                rs.getBigDecimal("amount"), rs.getDate("claim_date").toLocalDate(), rs.getString("note"),
165	                ClaimStatus.valueOf(rs.getString("status")), rs.getString("number"),
166	                rs.getBigDecimal("due"), rs.getString("opened_by"));
167	        claim.setStated(rs.getBoolean("stated"));
168	        claim.setStatedDue(rs.getBigDecimal("stated_due"));
169	        claim.setCorrects(rs.getString("corrects"));
170	        claim.setDueBy(rs.getDate("due_by").toLocalDate());
171	        return claim;
172	    }
173	}
