200	        this.settings = settings;
201	        this.sheets = sheets;
202	        this.claims = claims;
203	    }
204	
205	    /** The sheet's policy date: as set, else the sheet's today. */
206	    public LocalDate policyDate(String sheetId) {
207	        LocalDate set = settings.policyDate(sheetId);
208	        return set != null ? set : sheets.today(sheetId);
209	    }
210	
211	    /** How the claim's live figures round: half up when the claim is dated before the sheet's policy
212	     *  date, half to even on or after it. A correction rounds by the date of the claim it corrects. */
213	    public RoundingMode rounding(Claim claim) {
214	        return roundingDate(claim).isBefore(policyDate(claim.getSheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
215	    }
216	
217	    /** The date the claim rounds by: its own, or for a correction that of the claim it corrects. */
218	    public LocalDate roundingDate(Claim claim) {
219	        if (claim.getCorrects() == null) return claim.getDate();
220	        LocalDate corrected = claims.dateOf(claim.getSheetId(), claim.getPersonId(), claim.getCorrects());
221	        return corrected != null ? corrected : claim.getDate();
222	    }
223	
224	    /** The claim's due as the screen shows and totals it: its figure, plus its late charge while it
225	     *  is overdue. A settled claim's fixed due already holds the charge it had then. */
226	    public BigDecimal due(Claim claim, String grade) {
227	        BigDecimal figure = figure(claim, grade);
228	        if (figure == null || claim.getDue() != null) return figure;
229	        return figure.add(charge(claim, figure));
230	    }
231	
232	    /** The claim's figure without any late charge: the fixed due, else the bound figure, else live.
233	     *  A PENDING claim is not bound by a statement: it keeps its binding but shows its live figure. */
234	    public BigDecimal figure(Claim claim, String grade) {
235	        if (claim.getDue() != null) return claim.getDue();
236	        if (claim.isStated() && claim.getStatus() != ClaimStatus.PENDING) return claim.getStatedDue();
237	        return live(claim, grade);
238	    }
239	
240	    /** The late charge on a figure of the claim: nothing unless the claim is OPEN (or PENDING) and its due-by (fixed
241	     *  when it was added) is before the sheet's today; then the sheet's late percent of the
242	     *  figure for every full 30 days it is overdue (the late percent in force on the claim's date) (a correction has none), rounded by the claim's rounding to two decimals. Never bound
243	     *  by a statement: it follows the sheet's today. */
244	    public BigDecimal charge(Claim claim, BigDecimal figure) {
245	        BigDecimal none = BigDecimal.ZERO.setScale(2);
246	        if (figure == null || !claim.getStatus().isOpen() || claim.isCorrection()) return none;
247	        String sheetId = claim.getSheetId();
248	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheets.today(sheetId)) / 30;
249	        if (periods <= 0) return none;
250	        return figure.multiply(settings.latePct(sheetId, claim.getDate())).multiply(BigDecimal.valueOf(periods))
251	                .divide(BigDecimal.valueOf(100)).setScale(2, rounding(claim));
252	    }
253	
254	    /** The claim's due at its person's grade's rate in force on the claim's date: amount times the
255	     *  rate divided by 100, rounded by the claim's rounding to two decimals, raised to the sheet's floor in force on the claim's date when it
256	     *  is below it (a correction has no floor); null when there is no rate. */
257	    public BigDecimal live(Claim claim, String grade) {
258	        BigDecimal pct = rates.pct(claim.getSheetId(), grade, claim.getDate());
259	        if (pct == null) return null;
260	        BigDecimal due = claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100)).setScale(2, rounding(claim));
261	        return claim.isCorrection() ? due : due.max(settings.floor(claim.getSheetId(), claim.getDate()));
262	    }
263	}
