290	 *  the audit event it writes. */
291	public enum ClaimAction {
292	    OPEN(ClaimStatus.OPEN, "CLAIM_OPENED", ClaimStatus.DRAFT),
293	    SETTLE(ClaimStatus.SETTLED, "CLAIM_SETTLED", ClaimStatus.OPEN),
294	    APPROVE(ClaimStatus.SETTLED, "CLAIM_APPROVED", ClaimStatus.PENDING),
295	    REJECT(ClaimStatus.OPEN, "CLAIM_REJECTED", ClaimStatus.PENDING),
296	    VOID(ClaimStatus.VOID, "CLAIM_VOIDED", ClaimStatus.DRAFT, ClaimStatus.OPEN, ClaimStatus.PENDING);
297	
298	    private final ClaimStatus to;
299	    private final String event;
300	    private final ClaimStatus[] from;
301	
302	    ClaimAction(ClaimStatus to, String event, ClaimStatus... from) {
303	        this.to = to;
304	        this.event = event;
305	        this.from = from;
306	    }
307	
308	    public ClaimStatus to() { return to; }
309	    public String event() { return event; }
310	
311	    public boolean allowedFrom(ClaimStatus status) {
312	        for (ClaimStatus s : from) {
313	            if (s == status) return true;
314	        }
315	        return false;
316	    }
