328	/** Moves the claim to the action's status, refusing a change its current status does not allow.
329	 *  Opening gives the claim its number (see {@link ClaimNumbers}); a voided claim keeps it (and it is never reused).
330	 *  Settling fixes the claim's due at the figure it has then: the one its person's last statement
331	 *  bound it to, else its person's grade's rate in force on the claim's date, at least the sheet's floor, plus its late charge then; with no rate it stays live. The user who opened a claim may not settle it.
332	 *  When a clerk settles a claim whose due is over the sheet's clerk limit (a due of n/a is within any
333	 *  limit) it goes PENDING instead, its due still live; a steward settles anything. Only a steward
334	 *  approves a PENDING claim (it settles, its due fixed at its live figure then, plus its late charge),
335	 *  and never the user who opened it; a rejection sends it back to OPEN, bound again by the last
336	 *  statement if that bound it.
337	 *  A claim dated in a closed period cannot change status at all. */
338	public class ApplyClaimStatus {
339	    public void apply(@Val ClaimStatusChange change, @Val Claim claim, ClaimNumbers numbers, People people,
340	            Figures figures, ClosedPeriods closedPeriods, Settings settings)
341	            throws ClaimStatusRefusedException, PeriodClosedException {
342	        closedPeriods.refuse(claim.getSheetId(), claim.getDate());
343	        if (!change.action().allowedFrom(claim.getStatus())) {
344	            throw new ClaimStatusRefusedException(claim.getStatus(), change.action());
345	        }
346	        if (change.action() == ClaimAction.SETTLE && claim.getOpenedBy() != null
347	                && claim.getOpenedBy().equals(change.user())) {
348	            throw new ClaimStatusRefusedException("The user who opened a claim cannot settle it");
349	        }
350	        if (change.action() == ClaimAction.APPROVE) {
351	            if (claim.getOpenedBy() != null && claim.getOpenedBy().equals(change.user())) {
352	                throw new ClaimStatusRefusedException("The user who opened a claim cannot approve it");
353	            }
354	            if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD) {
355	                throw new ClaimStatusRefusedException("Only a steward can approve a pending claim");
356	            }
357	        }
358	        BigDecimal due = null;
359	        boolean pending = false;
360	        if (change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE) {
361	            String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
362	            // Figures.figure: the bound figure for an OPEN claim, the live one for a PENDING claim.
363	            due = figures.figure(claim, grade);
364	            if (due != null) due = due.add(figures.charge(claim, due));
365	            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
366	            pending = change.action() == ClaimAction.SETTLE && limit != null && due != null && due.compareTo(limit) > 0
367	                    && settings.role(claim.getSheetId(), change.user()) == Role.CLERK;
368	        }
369	        claim.setStatus(pending ? ClaimStatus.PENDING : change.action().to());
370	        if (change.action() == ClaimAction.OPEN) {
371	            claim.setNumber(numbers.next(claim));
372	            claim.setOpenedBy(change.user());
373	        }
374	        if ((change.action() == ClaimAction.SETTLE && !pending) || change.action() == ClaimAction.APPROVE) {
375	            claim.setDue(due);
376	        }
377	    }
378	}
