389	            throws InvalidSheetRequestException {
390	        String action = request == null || request.action() == null ? "" : request.action().trim();
391	        try {
392	            actor.set(new Actor(request.user()));
393	            ClaimAction parsed = ClaimAction.valueOf(action.toUpperCase(Locale.ROOT));
394	            String reason = request.reason() == null ? "" : request.reason().trim();
395	            if (parsed == ClaimAction.REJECT && reason.isEmpty()) {
396	                throw new InvalidSheetRequestException("A rejection needs a reason");
397	            }
398	            body.set(new ClaimStatusChange(parsed, request.user(), parsed == ClaimAction.REJECT ? reason : null));
399	        } catch (IllegalArgumentException e) {
400	            throw new InvalidSheetRequestException("Not a claim action (open, settle, approve, reject or void): " + action);
401	        }
402	    }
403	}
