412	public class RecordClaimStatusChanged {
413	    public void record(@Val ClaimStatusChange change, @Val Claim claim, People people, ClaimLog log, Audit audit) {
414	        log.write(claim, change.user());
415	        Person person = people.find(claim.getSheetId(), claim.getPersonId());
416	        // A clerk's settle over the clerk limit leaves the claim PENDING: it settles nothing yet.
417	        boolean pending = change.action() == ClaimAction.SETTLE && claim.getStatus() == ClaimStatus.PENDING;
418	        boolean fixesDue = !pending && (change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE);
419	        audit.record((pending ? "CLAIM_PENDING" : change.action().event()) + " sheet=" + claim.getSheetId() + " by=" + change.user()
420	                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
421	                + " date=" + claim.getDate() + (claim.getNumber() != null ? " number=" + claim.getNumber() : "")
422	                + (fixesDue ? " due=" + (claim.getDue() != null ? claim.getDue().toPlainString() : "n/a") : "")
423	                + (change.action() == ClaimAction.REJECT ? " reason=" + change.reason() : ""));
424	    }
