452	/** Re-settles a SETTLED claim: only a steward may, and never one dated in a closed period. Its due is
453	 *  fixed again at the figure it would have today as an OPEN claim bound by no statement: the rate of
454	 *  its person's grade in force on its date, at least the sheet's floor, plus its late charge today
455	 *  (n/a with no rate). It stays SETTLED, keeps its number and its binding. */
456	public class ApplyClaimResettle {
457	    public void apply(@Val ClaimResettle change, @Val Claim claim, People people, Figures figures,
458	            ClosedPeriods closedPeriods, Settings settings) throws ClaimStatusRefusedException, PeriodClosedException {
459	        if (settings.role(claim.getSheetId(), change.user()) != Role.STEWARD) {
460	            throw new ClaimStatusRefusedException("Only a steward can re-settle a claim");
461	        }
462	        if (claim.getStatus() != ClaimStatus.SETTLED) {
463	            throw new ClaimStatusRefusedException("Only a SETTLED claim can be re-settled");
464	        }
465	        closedPeriods.refuse(claim.getSheetId(), claim.getDate());
466	        Claim open = new Claim(claim.getId(), claim.getSheetId(), claim.getPersonId(), claim.getAmount(),
467	                claim.getDate(), claim.getNote(), ClaimStatus.OPEN, claim.getNumber(), null, claim.getOpenedBy());
468	        open.setCorrects(claim.getCorrects());
469	        open.setDueBy(claim.getDueBy());
470	        String grade = people.find(claim.getSheetId(), claim.getPersonId()).gradeOn(claim.getDate());
471	        change.setOld(claim.getDue());
472	        claim.setDue(figures.due(open, grade));
473	    }
474	}
