618	-- it was added, then one per change. Each keeps who made it, the sheet's today then, and the claim's
619	-- due as it was worked out at that moment (null for n/a). Claims already kept have no lines.
620	CREATE TABLE claim_log (
621	    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
622	    sheet_id VARCHAR(200)  NOT NULL,
623	    claim_id BIGINT        NOT NULL REFERENCES claim (id),
624	    status   VARCHAR(20)   NOT NULL,
