630	-- A person may have several holds over time, each from a date and, optionally, to a date (both
631	-- inclusive; no to-date: open-ended). Only their OPEN claims dated within a hold are left out of the
632	-- live totals; a claim bound by a statement stays in whatever its date. A person held before keeps
633	-- one open-ended hold from the beginning of time.
634	CREATE TABLE person_hold (
635	    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
636	    sheet_id  VARCHAR(200) NOT NULL,
