388	    public Rollup(People people, Claims claims, Figures figures, Rates rates, Sheets sheets, Audit audit, Settings settings) {
389	        this.people = people;
390	        this.claims = claims;
391	        this.figures = figures;
392	        this.rates = rates;
393	        this.sheets = sheets;
394	        this.audit = audit;
395	        this.settings = settings;
396	    }
397	
398	    /** The sheet's figures now. A person's due-total is the sum of their counting claims' figures (a
399	     *  person's OPEN claims dated within a hold of theirs do not count, unless a statement binds them),
400	     *  n/a when there is no rate today and none has a figure, at most the sheet's cap (n/a is not
401	     *  capped); the sheet's skips the n/a ones. */
402	    public Snapshot snapshot(String sheetId) {
403	        LocalDate today = sheets.today(sheetId);
404	        List<Claim> all = claims.onSheet(sheetId);
405	        Map<Long, Snapshot.PersonFigures> figuresOf = new LinkedHashMap<>();
406	        BigDecimal claimedTotal = ZERO;
407	        BigDecimal dueTotal = ZERO;
408	        BigDecimal overdueTotal = ZERO;
409	        for (Person person : people.onSheet(sheetId)) {
410	            BigDecimal claimed = ZERO;
411	            BigDecimal due = ZERO;
412	            BigDecimal overdue = ZERO;
413	            boolean any = false;
414	            for (Claim claim : all) {
415	                if (claim.getPersonId() != person.getId() || !person.counts(claim)) continue;
416	                claimed = claimed.add(claim.getAmount());
417	                BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
418	                if (figure != null) {
419	                    due = due.add(figure);
420	                    any = true;
421	                    if (claim.getStatus().isOpen() && today != null && claim.getDueBy().isBefore(today)) {
422	                        overdue = overdue.add(figure);
423	                    }
424	                }
425	            }
426	            if (!any && rates.pct(sheetId, person.gradeOn(today), today) == null) due = null;
427	            due = settings.capped(sheetId, due);
428	            figuresOf.put(person.getId(), new Snapshot.PersonFigures(person.getName(), claimed, due, overdue));
429	            claimedTotal = claimedTotal.add(claimed);
430	            if (due != null) dueTotal = dueTotal.add(due);
431	            overdueTotal = overdueTotal.add(overdue);
432	        }
433	        return new Snapshot(figuresOf, claimedTotal, dueTotal, overdueTotal);
434	    }
435	
436	    /** Audit the figures that moved between `before` and the sheet now. */
437	    public void record(String sheetId, Snapshot before, String user) {
438	        Snapshot after = snapshot(sheetId);
439	        String prefix = " sheet=" + sheetId + " by=" + user;
440	        after.people().forEach((id, now) -> {
441	            Snapshot.PersonFigures was = before.people().get(id);
442	            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
443	                    && same(was.overdueTotal(), now.overdueTotal())) return;
444	            audit.record("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + show(now.claimed())
445	                    + " due-total=" + show(now.dueTotal()) + " overdue-total=" + show(now.overdueTotal()));
446	        });
447	        if (!same(before.claimedTotal(), after.claimedTotal()) || !same(before.dueTotal(), after.dueTotal())
448	                || !same(before.overdueTotal(), after.overdueTotal())) {
449	            audit.record("TOTALS" + prefix + " claimed-total=" + show(after.claimedTotal())
450	                    + " due-total=" + show(after.dueTotal()) + " overdue-total=" + show(after.overdueTotal()));
451	        }
452	    }
453	
454	    private static boolean same(BigDecimal a, BigDecimal b) {
455	        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
456	    }
457	
458	    private static String show(BigDecimal value) {
459	        return value == null ? "n/a" : value.setScale(2).toPlainString();
460	    }
461	}
