474	/** Takes the person's statement: their due-total now, the sum of their counting claims' figures
475	 *  with any late charges (n/a when there is no rate today and none has a figure), at most the sheet's cap, dated the sheet's today. Every claim
476	 *  of theirs that counts (not an OPEN one dated within one of their holds) is bound to the figure it has now, without its late charge; every other one is unbound. */
477	public class TakeStatement {
478	    public void take(@Val StatementRequest request, @Val Person person, Claims claims, Figures figures,
479	            Rates rates, Sheets sheets, Settings settings, People people, Out<Statement> statement) {
480	        Person locked = people.lock(person.getSheetId(), person.getId());
481	        person.setStatementCount(locked.getStatementCount());
482	        BigDecimal total = BigDecimal.ZERO.setScale(2);
483	        boolean any = false;
484	        int counted = 0;
485	        for (Claim claim : claims.ofPerson(person.getSheetId(), person.getId())) {
486	            if (person.counts(claim)) {
487	                BigDecimal bound = figures.figure(claim, person.gradeOn(claim.getDate()));
488	                // The statement binds the figure; the late charge on top keeps following today.
489	                BigDecimal figure = bound == null || claim.getDue() != null ? bound : bound.add(figures.charge(claim, bound));
490	                claim.setStated(true);
491	                claim.setStatedDue(bound);
492	                counted++;
493	                if (figure != null) {
494	                    total = total.add(figure);
495	                    any = true;
496	                }
497	            } else {
498	                claim.setStated(false);
499	                claim.setStatedDue(null);
500	            }
501	            claims.save(claim);
502	        }
503	        var today = sheets.today(person.getSheetId());
504	        BigDecimal dueTotal = !any && rates.pct(person.getSheetId(), person.gradeOn(today), today) == null ? null
505	                : settings.capped(person.getSheetId(), total);
506	        person.setStatementCount(person.getStatementCount() + 1);
507	        person.setStatedTotal(dueTotal);
508	        person.setStatementDate(today);
509	        people.saveStatement(person);
510	        statement.set(new Statement(dueTotal, counted, request.user()));
511	    }
512	}
