593	/** Closes the period, fixing its due-total as the screen shows it now: the figures of everyone's
594	 *  counted (OPEN or SETTLED) claims dated in it — not
595	 *  the OPEN ones dated within their person's hold, unless stated — n/a ones skipped. A closed period cannot be
596	 *  closed again. Each person's due-total for it is fixed too, and the
597	 *  period's is their sum. Publishes the closed period. */
598	public class ClosePeriod {
599	    public void close(@Val Period period, Periods periods, Claims claims, People people, Figures figures,
600	            Out<ClosedPeriod> closed) throws PeriodClosedException {
601	        if (period.closed()) throw new PeriodClosedException("Period " + period.name() + " is already closed");
602	        Map<Long, Person> personOf = people.onSheet(period.sheetId()).stream()
603	                .collect(Collectors.toMap(Person::getId, p -> p));
604	        Map<Long, BigDecimal> personTotals = new LinkedHashMap<>();
605	        for (Long id : personOf.keySet()) personTotals.put(id, BigDecimal.ZERO.setScale(2));
606	        for (Claim claim : claims.onSheet(period.sheetId())) {
607	            if (!period.contains(claim.getDate())) continue;
608	            Person person = personOf.get(claim.getPersonId());
609	            if (person == null || !person.counts(claim)) continue;
610	            BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
611	            if (figure != null) personTotals.merge(person.getId(), figure, BigDecimal::add);
612	        }
613	        BigDecimal total = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
614	        periods.close(period, total, personTotals);
615	        closed.set(new ClosedPeriod(new Period(period.sheetId(), period.name(), period.from(), period.to(), true, total)));
616	    }
617	}
