/** A person as the screen sees it, with their statement count, and the last statement's due-total
 *  (two decimals, null when it was n/a or none was taken) and date (yyyy-mm-dd, null when none was),
 *  and whether they are retired and from when (yyyy-mm-dd, null when not retired),
 *  and whether they have any hold and each hold's dates, and the ids of the people they have named as patrons. `grade` is
 *  the grade in force on the sheet's today; `grades` every grade recorded, by from-date (null: from
 *  the beginning of time, first). */
public record PersonResponse(long id, String name, String grade, int version, int statementCount,
        String statedTotal, String statementDate, boolean retired, String retiredFrom,
        boolean held, List<HoldDates> holds, List<Long> patrons, List<GradeFrom> grades) {

    /** A hold's dates (yyyy-mm-dd; `to` null: open-ended). */
    public record HoldDates(String from, String to) {
    }

    public record GradeFrom(String grade, String from) {
    }

    public static PersonResponse from(Person person) {
        return new PersonResponse(person.getId(), person.getName(), person.getGrade(), person.getVersion(),
                person.getStatementCount(),
                person.getStatedTotal() != null ? person.getStatedTotal().toPlainString() : null,
                person.getStatementDate() != null ? person.getStatementDate().toString() : null,
                person.isRetired(), person.getRetiredFrom() != null ? person.getRetiredFrom().toString() : null,
                person.isHeld(),
                person.getHolds().stream()
                        .map(h -> new HoldDates(h.from().toString(), h.to() != null ? h.to().toString() : null))
                        .toList(),
                List.copyOf(person.getPatronIds()),
                person.getGrades().entrySet().stream()
                        .map(e -> new GradeFrom(e.getValue(), e.getKey().equals(LocalDate.MIN) ? null : e.getKey().toString()))
                        .toList());
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/**
 * The figures the screen shows — each person's claimed and due-total, the sheet's claimed-total and
 * due-total, and each one's overdue-total and the sheet's — worked out as the screen does, so a change can audit the ones it moved: one ROLLUP
 * line per person whose figures changed (a new person counts as changed), then a TOTALS line when
 * the sheet's totals changed.
 */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private final People people;
    private final Claims claims;
    private final Figures figures;
    private final Rates rates;
    private final Sheets sheets;
    private final Audit audit;
    private final Settings settings;

    public Rollup(People people, Claims claims, Figures figures, Rates rates, Sheets sheets, Audit audit, Settings settings) {
        this.people = people;
        this.claims = claims;
        this.figures = figures;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.settings = settings;
    }

    /** The sheet's figures now. A person's due-total is the sum of their counting claims' figures (a
     *  person's OPEN claims dated within a hold of theirs do not count, unless a statement binds them),
     *  n/a when there is no rate today and none has a figure, at most the sheet's cap (n/a is not
     *  capped); the sheet's skips the n/a ones. */
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> all = claims.onSheet(sheetId);
        Map<Long, Snapshot.PersonFigures> figuresOf = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        BigDecimal dueTotal = ZERO;
        BigDecimal overdueTotal = ZERO;
        for (Person person : people.onSheet(sheetId)) {
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            BigDecimal overdue = ZERO;
            boolean any = false;
            for (Claim claim : all) {
                if (claim.getPersonId() != person.getId() || !person.counts(claim)) continue;
                claimed = claimed.add(claim.getAmount());
                BigDecimal figure = figures.due(claim, person.gradeOn(claim.getDate()));
                if (figure != null) {
                    due = due.add(figure);
                    any = true;
                    if (claim.getStatus().isOpen() && today != null && claim.getDueBy().isBefore(today)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            if (!any && rates.pct(sheetId, person.gradeOn(today), today) == null) due = null;
            due = settings.capped(sheetId, due);
            figuresOf.put(person.getId(), new Snapshot.PersonFigures(person.getName(), claimed, due, overdue));
            claimedTotal = claimedTotal.add(claimed);
            if (due != null) dueTotal = dueTotal.add(due);
            overdueTotal = overdueTotal.add(overdue);
        }
        return new Snapshot(figuresOf, claimedTotal, dueTotal, overdueTotal);
    }

    /** Audit the figures that moved between `before` and the sheet now. */
    public void record(String sheetId, Snapshot before, String user) {
        Snapshot after = snapshot(sheetId);
        String prefix = " sheet=" + sheetId + " by=" + user;
        after.people().forEach((id, now) -> {
            Snapshot.PersonFigures was = before.people().get(id);
            if (was != null && same(was.claimed(), now.claimed()) && same(was.dueTotal(), now.dueTotal())
                    && same(was.overdueTotal(), now.overdueTotal())) return;
            audit.record("ROLLUP" + prefix + " person=" + now.name() + " claimed=" + show(now.claimed())
                    + " due-total=" + show(now.dueTotal()) + " overdue-total=" + show(now.overdueTotal()));
        });
        if (!same(before.claimedTotal(), after.claimedTotal()) || !same(before.dueTotal(), after.dueTotal())
                || !same(before.overdueTotal(), after.overdueTotal())) {
            audit.record("TOTALS" + prefix + " claimed-total=" + show(after.claimedTotal())
                    + " due-total=" + show(after.dueTotal()) + " overdue-total=" + show(after.overdueTotal()));
        }
    }

    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null || b == null ? Objects.equals(a, b) : a.compareTo(b) == 0;
    }

    private static String show(BigDecimal value) {
        return value == null ? "n/a" : value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Figures;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.settings.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Takes the person's statement: their due-total now, the sum of their counting claims' figures
 *  with any late charges (n/a when there is no rate today and none has a figure), at most the sheet's cap, dated the sheet's today. Every claim
 *  of theirs that counts (not an OPEN one dated within one of their holds) is bound to the figure it has now, without its late charge; every other one is unbound. */
public class TakeStatement {
    public void take(@Val StatementRequest request, @Val Person person, Claims claims, Figures figures,
            Rates rates, Sheets sheets, Settings settings, People people, Out<Statement> statement) {
        Person locked = people.lock(person.getSheetId(), person.getId());
        person.setStatementCount(locked.getStatementCount());
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean any = false;
        int counted = 0;
        for (Claim claim : claims.ofPerson(person.getSheetId(), person.getId())) {
            if (person.counts(claim)) {
                BigDecimal bound = figures.figure(claim, person.gradeOn(claim.getDate()));
                // The statement binds the figure; the late charge on top keeps following today.
                BigDecimal figure = bound == null || claim.getDue() != null ? bound : bound.add(figures.charge(claim, bound));
                claim.setStated(true);
                claim.setStatedDue(bound);
                counted++;
                if (figure != null) {
                    total = total.add(figure);
                    any = true;
                }
            } else {
                claim.setStated(false);
                claim.setStatedDue(null);
            }
            claims.save(claim);
        }
        var today = sheets.today(person.getSheetId());
        BigDecimal dueTotal = !any && rates.pct(person.getSheetId(), person.gradeOn(today), today) == null ? null
                : settings.capped(person.getSheetId(), total);
        person.setStatementCount(person.getStatementCount() + 1);
        person.setStatedTotal(dueTotal);
        person.setStatementDate(today);
        people.saveStatement(person);
        statement.set(new Statement(dueTotal, counted, request.user()));
    }
}
